create extension if not exists pg_cron;
select cron.schedule('daily-vaccine-reminders','0 8 * * *',$$select net.http_post(url:=current_setting('app.settings.reminder_url')::text,headers:=jsonb_build_object('Authorization','Bearer '||current_setting('app.settings.cron_secret')),body:='{"source":"scheduled"}'::jsonb)$$);
create function public.apply_approved_retention(p_soft_deleted_before timestamptz,p_audit_before timestamptz) returns jsonb language plpgsql security definer set search_path='' as $$declare pets_removed int;events_removed int;begin delete from public.pets p where p.deleted_at<p_soft_deleted_before and not exists(select 1 from public.profiles owner where owner.id=p.owner_id and owner.legal_hold_until>=current_date);get diagnostics pets_removed=row_count;delete from public.admin_audit_events where created_at<p_audit_before;get diagnostics events_removed=row_count;return jsonb_build_object('pets_removed',pets_removed,'events_removed',events_removed);end$$;
revoke all on function public.apply_approved_retention(timestamptz,timestamptz) from public,anon,authenticated;
